function animateDoors(open, done){
  if(doorsAnimating){ if(done) done(); return; }
  doorsAnimating = true;
  const leftDoor = elevatorCar.leftDoor;
  const rightDoor = elevatorCar.rightDoor;
  const startLeftX = leftDoor.position.x;
  const startRightX = rightDoor.position.x;
  const targetLeftX = open ? -doorWidth*1.2 : -doorWidth/2;
  const targetRightX = open ? doorWidth*1.2 : doorWidth/2;
  const duration = 0.5 / speedMultiplier;
  const startTime = performance.now();
  function step(now){
    const elapsed = (now - startTime)/1000;
    const t = Math.min(elapsed/duration,1);
    leftDoor.position.x = startLeftX + (targetLeftX - startLeftX)*t;
    rightDoor.position.x = startRightX + (targetRightX - startRightX)*t;
    if(t < 1){
      requestAnimationFrame(step);
    }else{
      doorsAnimating = false;
      if(done) done();
    }
  }
  requestAnimationFrame(step);
}

